USE `lab05_weka_model`;

DROP TABLE IF EXISTS `customer_service_data`;

CREATE TABLE `customer_service_data` (
    `channel_name` VARCHAR(255) NULL,
    `category` VARCHAR(255) NULL,
    `Sub-category` VARCHAR(255) NULL,
    `Customer_City` VARCHAR(255) NULL,
    `Product_category` VARCHAR(255) NULL,
    `Item_price` FLOAT NULL,
    `connected_handling_time` FLOAT NULL,
    `Agent_name` VARCHAR(255) NULL,
    `Supervisor` VARCHAR(255) NULL,
    `Manager` VARCHAR(255) NULL,
    `Tenure Bucket` VARCHAR(255) NULL,
    `Agent Shift` VARCHAR(255) NULL,
    `Satisfaction` VARCHAR(255) NULL
);

